            self.publication_year = new_year
        else:
            raise ValueError("Publication year must be a positive integer.")

    def is_published_before(self, other_year):
        return self.publication_year < other_year

    def is_published_after(self, other_year):
        return self.publication_year > other_year

    def is_same_year(self, other_year):
        return self.publication_year == other_year
