// Function to merge two sorted arrays in-place
void mergeArrays(std::vector<int>& arr1, const std::vector<int>& arr2) {
    // Check if the arrays are valid
    if (arr1.empty() || arr2.empty()) {
        throw std::invalid_argument("Arrays cannot be empty.");
    }

    int n = arr1.size();
    int m = arr2.size();

    // Initialize pointers
    int i = n - 1; // Pointer for arr1
    int j = m - 1; // Pointer for arr2
    int k = n + m - 1; // Pointer for the merged array (end of arr1)

    // Merge the arrays from the end
    while (i >= 0 && j >= 0) {
        if (arr1[i] > arr2[j]) {
            arr1[k] = arr1[i];
            i--;
        } else {
            arr1[k] = arr2[j];
            j--;
        }
        k--;
    }

    // If there are remaining elements in arr2, copy them to arr1
    while (j >= 0) {
        arr1[k] = arr2[j];
        j--;
        k--;
    }
}

int main() {
